{
  "outcome": "escalate",
  "rationale": "We have escalated this claim because it is unclear whether an exclusion applies due to disputed or missing material facts regarding the driver's license status. Section 6.2 governs this referral since the submitted details leave coverage open to more than one reasonable reading. Consequently, the claim must be escalated for further investigation.",
  "citations": [
    {
      "clause_id": "STD-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
